// nodeTypeAliasLabel returns the user-facing label for a node type. View
// renders as "opinion" and finding as "evidence"; the chip's CSS uppercases
// the result. Topic and comment stay as they are.
func nodeTypeAliasLabel(t db.NodeType) string {
	switch t {
	case db.NodeTypeView:
		return "opinion"
	case db.NodeTypeFinding:
		return "evidence"
	}
	return string(t)
}

// nodeTypeOriginalLabel returns the capitalised user-facing name for the
// title tooltip on chips and buttons. The backend term ("finding") is
// masked here so users never see it during the rename to "evidence".
func nodeTypeOriginalLabel(t db.NodeType) string {
	switch t {
	case db.NodeTypeView:
		return "View"
	case db.NodeTypeFinding:
		return "Evidence"
	case db.NodeTypeTopic:
		return "Topic"
	case db.NodeTypeComment:
		return "Comment"
	}
	return string(t)
}

